import pytest
from fastapi import FastAPI, Depends, Response, Request
from fastapi.testclient import TestClient
from typing import Annotated

app = FastAPI()

def modify_response():
    return Response(content="modified", media_type="text/plain")

def get_request(request: Request):
    return request

@app.get("/response-annotated")
def endpoint_response_annotated(response: Annotated[Response, Depends(modify_response)]):
    return {"message": "success"}

@app.get("/response-default")
def endpoint_response_default(response: Response = Depends(modify_response)):
    return {"message": "success"}

@app.get("/response-regular")
def endpoint_response_regular(response: Response):
    return {"message": "success"}

@app.get("/request-annotated")
def endpoint_request_annotated(request: Annotated[Request, Depends(get_request)]):
    return {"message": "success"}

client = TestClient(app)

def test_response_annotated():
    response = client.get("/response-annotated")
    assert response.status_code == 200
    assert response.json() == {"message": "success"}

def test_response_default():
    response = client.get("/response-default")
    assert response.status_code == 200
    assert response.json() == {"message": "success"}

def test_response_regular():
    response = client.get("/response-regular")
    assert response.status_code == 200
    assert response.json() == {"message": "success"}

def test_request_annotated():
    response = client.get("/request-annotated")
    assert response.status_code == 200
    assert response.json() == {"message": "success"}

